@six.add_metaclass(ABCMeta)
class MessageSource(object):
    '''
    Interface that all specific MessageSources should fulfill

    MessageSource should parse incoming protocol stream and sent UnparsedMessages to the provided queue.
    Parsing doesn't mean full parsing (possible but not required).
    Rather it is extracting message from data stream.
    .
    Means:

    * message payload (from msg start till msg end)
    * message type
    * message ownership if any (like RRC msg of given UE)
    * message occurrence time.

    Moreover, it is responsible to embed specific parser inside UnparsedMessage to allow for dalayed full-parsing.
    Only specific data source knows which parser should be used since specific data source is highly coupled
    with format of data stream.
    We prefer such 2 step parsing model since some clients consuming messages are interested only in very basic
    information about message (stated above). Full parsing is waste for them.
    '''
    MAX_CSV_PARSING_TIME_SECONDS = 60 * 5

    def __init__(self, queue):
        self.queue = queue
        self.logger = msg_logging.configure_msg_source_logger(self._src_name())
        self.csv_logger = None
        self.additional_csv_loggers = {}
        self.csv_logger_columns = None
        self.logger.debug("%s creating" % self)
        self.source_specific_parser = None
        self.is_running = threading.Event()
        self._main_loop_finished = threading.Semaphore(0)
        self._source_started = threading.Semaphore(0)

    def setup_csv_logger(self, *additional_columns):
        '''
        Setup csv logger, that can be used by message sources to provide input for parsing script.
        '''
        self.csv_logger = msg_logging.configure_msg_source_csv_logger(self._src_name())
        self.csv_logger_columns = ['date', 'time', 'protocol', 'message_type', 'hex']
        if len(additional_columns):
            self.csv_logger_columns.extend(additional_columns)
        self.csv_logger.debug(";".join(self.csv_logger_columns))

    def setup_additional_csv_logger(self, logger_unique_prefix):
        """
        Setups additional csv logger
        """
        assert self.csv_logger is not None, 'Main csv logger for source must be configured first'
        assert logger_unique_prefix not in self.additional_csv_loggers, 'CSV logger with prefix: {} already exists'
        additional_logger_name = "{}_{}".format(logger_unique_prefix, self._src_name())
        add_csv_logger = msg_logging.configure_msg_source_csv_logger(additional_logger_name)
        add_csv_logger.debug(";".join(self.csv_logger_columns))
        self.additional_csv_loggers[additional_logger_name] = add_csv_logger

    def release_additional_csv_logger(self, logger_unique_prefix):
        """
        Removes additional csvn loger
        """
        try:
            del self.additional_csv_loggers[logger_unique_prefix]
        except Exception:
            self.logger.debug('Additional csv logger: {} could not be removed as not existing'
                              .format(logger_unique_prefix))

    def log_to_csv(self, *additional_columns, **mandatory_params):
        '''
        Logs data to csv logger if setup_csv_logger invoked earlier.
        '''
        if self.csv_logger is not None:
            try:
                msg_date, msg_time = str(datetime.datetime.now().date()), str(datetime.datetime.now().time())
                args = [msg_date, msg_time, mandatory_params['protocol'],
                        mandatory_params['message_type'],
                        mandatory_params['hex']]
                if len(additional_columns):
                    args.extend(additional_columns)
                self.csv_logger.debug(";".join(args))
                if len(self.additional_csv_loggers):
                    for add_csv_logger in list(self.additional_csv_loggers.values()):
                        add_csv_logger.debug(";".join(args))
            except Exception as e:
                self.logger.warn('CSV logger: {}'.format(e))

    @abstractproperty
    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        pass

    def __repr__(self):
        class_name = self.__class__.__name__
        queue_name = 'Que:{}'.format(hex(id(self.queue)))  # important in debugs since it is used for subscriptions
        return '%s(%s, %s)' % (class_name, self._src_name(), queue_name)

    def __str__(self):
        class_name = self.__class__.__name__
        return '%s(%s)' % (class_name, self._src_name())

    def start(self):
        '''
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages and sending them to the output queue
        '''
        self.is_running.set()
        self._source_started.release()
        self.logger.debug('{!r} thread started'.format(self))
        while self.is_running.is_set():
            protocol_data = self._get_protocol_data()
            if protocol_data is None:
                break
            self.logger.trace('%s: << %s' % (self, pprint.pformat(protocol_data)))
            self._put_to_queue(*self._get_unparsed_messages(protocol_data))
        self._main_loop_finished.release()
        self.logger.debug('{!r} thread finished'.format(self))

    def stop(self):
        '''
        Stops message source loop and perfoms cleanup
        '''
        if self.is_running.is_set():
            self.is_running.clear()
            self._main_loop_finished.acquire()
            self._close_connection()
        self.logger.debug('%s stopped' % self)
        self.parse_csv_logs()

    def parse_csv_logs(self, log_prefix_filter=None):
        '''
        Parses csv logs if available
        '''
        robot_var = None
        try:
            robot_var = BuiltIn().get_variable_value('${TA_MESSAGING_DISABLE_CSV_LOGGING}', None)
        except RobotNotRunningError:
            pass
        if robot_var is not None:
            self.logger.debug('{}: parsing csv logs aborted due to TA_MESSAGING_DISABLE_CSV_LOGGING variable set'.format(str(self)))
            # if value is declared, means user wants to disable csv logging
            return
        start_time = time.time()
        try:
            if self.csv_logger is not None:
                source_name = self._src_name() if log_prefix_filter is None else log_prefix_filter
                csv_logs = find_csv_logs(source_name)
                if len(csv_logs):
                    self.logger.debug('{}: started parsing csv logs, it may take verfy long time, depending on number of logs'.format(str(self)))
                    outcome_message = parse_csv_logs(csv_logs, MessageSource.MAX_CSV_PARSING_TIME_SECONDS)
                    elapsed_time = int(time.time() - start_time)
                    if outcome_message == OUTCOME_OK:
                        self.logger.debug('{}: csv log successfully parsed after: {}s'.format(str(self), elapsed_time))
                    elif outcome_message == OUTCOME_TIMEOUT:
                        self.logger.debug('{}: csv log parsing stopped after: {}s due to exceeding time limit'
                                          .format(str(self), elapsed_time))
                else:
                    self.logger.debug('{}: no csv log matching: {} found'.format(str(self), self._src_name()))
        except Exception as e:
            elapsed_time = int(time.time() - start_time)
            self.logger.debug('{}: csv log parsing failed after: {}s'.format(str(self), elapsed_time))
            self.logger.warn('{} parsing csv logs failed/partially failed with exception: {}\n{}'.format(str(self), e, traceback.format_exc()))

    @abstractproperty
    def _read(self):
        '''
        Returns data chunk from data stream (inheritance API)

        :return: data_chunk: string
        '''
        pass

    @abstractproperty
    def _get_protocol_data(self):
        '''
        Returns valid protocol data combined from data stream chunks.

        Valid data encapsulate whole messages - truncation is forbidden (inheritance API).

        :return: protocol data
        '''
        pass

    @abstractproperty
    def _get_unparsed_messages(self, protocol_data):
        '''
        Returns list of unparsed_messages extracted from protocol_data (inheritance API)

        :param protocol_data: data chunks that encapsulated whole messages
        :return: list of UnparsedMessage instances
        '''
        pass

    @abstractproperty
    def _get_opened_connection(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        pass

    @abstractproperty
    def _close_connection(self):
        '''
        Closes connection to data stream (inheritance API)

        :return: None
        '''
        pass

    def _start_in_separate_thread(self):
        threading.Thread(target=self.start).start()
        self._source_started.acquire()
        self.logger.debug("%s started" % self)

    def _put_to_queue(self, *args):
        for arg in args:
            self.logger.trace('%s: >> %s' % (self, str(arg)))
            self.queue.put(arg)


def _is_address_ipv6(address):
    return True if ':' in str(address) else False


def _map_from_net_elem_identification_to_source_class(net_elem_identification):
    sources_def = []

    construction_generator = TestEnv().get_message_source_construction_generator(network_elem_type=net_elem_identification.network_elem_type,
                                                                                 variant=net_elem_identification.specific_for_tool,
                                                                                 id_of_variant=net_elem_identification.tool_specific_id)
    for recipe in construction_generator:
        class_name, constructor_args = recipe
        sources_def.append((class_name, constructor_args))
    return sources_def

    return sources_def


def create_and_start_additional_sources(net_elem_identification):
    """
    Factory method to create different message source based on NetworkElementIdentification
    """
    message_sources = []
    sources_def = _map_from_net_elem_identification_to_source_class(net_elem_identification)
    for source_class_name, source_params in sources_def:  # TODO: change it to be really source_class, source_params
        class_params = dict()
        class_params['queue'] = Queue()
        class_params.update(source_params)
        # msg_source = create_instance_from_class_fullname(source_class_name, class_params)
        msg_source_class = instance_loader.load_class_from_class_fullname(class_fullname=source_class_name)
        msg_source = instance_loader.create_class_instance(class_object=msg_source_class, constructor_params=class_params)
        # except:
        #     raise MessageSourceNotImplemented(source_class)
        message_sources.append(msg_source)
    return message_sources


def check_if_interface_exists(interface_name):
    '''
    Returns True if interface exists on machine when python runs, otherwise False.

    :param interface_name:
    :return:
    '''
    interface_name = str(interface_name)
    available_interfaces = os.listdir('/sys/class/net/')
    return True if interface_name in available_interfaces else False
